1	package com.maritime.platform.common.web.handler;
2	
3	import com.maritime.platform.common.core.exception.BusinessException;
4	import com.maritime.platform.common.core.result.R;
5	import com.maritime.platform.common.core.result.ResultCode;
6	import jakarta.servlet.http.HttpServletRequest;
7	import java.util.stream.Collectors;
8	import org.slf4j.Logger;
9	import org.slf4j.LoggerFactory;
10	import org.slf4j.MDC;
11	import org.springframework.http.HttpStatus;
12	import org.springframework.http.converter.HttpMessageNotReadableException;
13	import org.springframework.lang.NonNull;
14	import org.springframework.validation.BindException;
15	import org.springframework.web.HttpMediaTypeNotSupportedException;
16	import org.springframework.web.HttpRequestMethodNotSupportedException;
17	import org.springframework.web.bind.MethodArgumentNotValidException;
18	import org.springframework.web.bind.MissingServletRequestParameterException;
19	import org.springframework.web.bind.annotation.ExceptionHandler;
20	import org.springframework.web.bind.annotation.ResponseStatus;
21	import org.springframework.web.bind.annotation.RestControllerAdvice;
22	import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;
23	import org.springframework.web.servlet.resource.NoResourceFoundException;
24	
25	/**
26	 * Centralized exception handler that translates exceptions into unified
27	 * {@link R} responses.
28	 *
29	 * <p>Every error response includes:
30	 * <ul>
31	 *   <li>{@code traceId} — distributed trace correlation ID from MDC</li>
32	 *   <li>{@code path} — the request URI that triggered the error</li>
33	 *   <li>{@code timestamp} — ISO-8601 timestamp (set by {@link R} constructor)</li>
34	 * </ul>
35	 */
36	@RestControllerAdvice
37	public class GlobalExceptionHandler {
38	
39	    private static final Logger LOG =
40	            LoggerFactory.getLogger(GlobalExceptionHandler.class);
41	    private static final String TRACE_ID_KEY = "traceId";
42	
43	    @ExceptionHandler(BusinessException.class)
44	    @ResponseStatus(HttpStatus.OK)
45	    public R<Object> handleBusiness(BusinessException ex,
46	                                    HttpServletRequest request) {
47	        LOG.warn("Business exception: code={}, message={}",
48	                ex.getCode(), ex.getMessage());
49	        R<Object> result = R.fail(ex.getCode(), ex.getMessage());
50	        if (ex.getData() != null) {
51	            result.setData(ex.getData());
52	        }
53	        result.setTraceId(MDC.get(TRACE_ID_KEY));
54	        result.setPath(request.getRequestURI());
55	        return result;
56	    }
57	
58	    @ExceptionHandler(MethodArgumentNotValidException.class)
59	    @ResponseStatus(HttpStatus.BAD_REQUEST)
60	    public R<Void> handleValidation(MethodArgumentNotValidException ex,
61	                                    HttpServletRequest request) {
62	        String detail = ex.getBindingResult().getFieldErrors().stream()
63	                .map(e -> e.getField() + ": " + e.getDefaultMessage())
64	                .collect(Collectors.joining("; "));
65	        LOG.warn("Validation failed: {}", detail);
66	        return buildError(ResultCode.PARAM_INVALID, detail, request);
67	    }
68	
69	    @ExceptionHandler(BindException.class)
70	    @ResponseStatus(HttpStatus.BAD_REQUEST)
71	    public R<Void> handleBind(BindException ex,
72	                              HttpServletRequest request) {
73	        String detail = ex.getFieldErrors().stream()
74	                .map(e -> e.getField() + ": " + e.getDefaultMessage())
75	                .collect(Collectors.joining("; "));
76	        LOG.warn("Bind exception: {}", detail);
77	        return buildError(ResultCode.PARAM_INVALID, detail, request);
78	    }
79	
80	    @ExceptionHandler(MissingServletRequestParameterException.class)
81	    @ResponseStatus(HttpStatus.BAD_REQUEST)
82	    public R<Void> handleMissingParam(
83	            MissingServletRequestParameterException ex,
84	            HttpServletRequest request) {
85	        LOG.warn("Missing parameter: {}", ex.getParameterName());
86	        return buildError(ResultCode.PARAM_INVALID,
87	                ex.getMessage(), request);
88	    }
89	
90	    @ExceptionHandler(MethodArgumentTypeMismatchException.class)
91	    @ResponseStatus(HttpStatus.BAD_REQUEST)
92	    public R<Void> handleTypeMismatch(
93	            MethodArgumentTypeMismatchException ex,
94	            HttpServletRequest request) {
95	        String detail = "Parameter '" + ex.getName()
96	                + "' type mismatch: expected "
97	                + getSimpleTypeName(ex) + "";
98	        LOG.warn("Type mismatch: {}", detail);
99	        return buildError(ResultCode.PARAM_INVALID, detail, request);
100	    }
101	
102	    @ExceptionHandler(HttpMessageNotReadableException.class)
103	    @ResponseStatus(HttpStatus.BAD_REQUEST)
104	    public R<Void> handleNotReadable(
105	            HttpMessageNotReadableException ex,
106	            HttpServletRequest request) {
107	        LOG.warn("Message not readable: {}", ex.getMessage());
108	        return buildError(ResultCode.BAD_REQUEST, request);
109	    }
110	
111	    @ExceptionHandler(HttpRequestMethodNotSupportedException.class)
112	    @ResponseStatus(HttpStatus.METHOD_NOT_ALLOWED)
113	    public R<Void> handleMethodNotAllowed(
114	            HttpRequestMethodNotSupportedException ex,
115	            HttpServletRequest request) {
116	        LOG.warn("Method not allowed: {}", ex.getMethod());
117	        return buildError(ResultCode.METHOD_NOT_ALLOWED, request);
118	    }
119	
120	    @ExceptionHandler(HttpMediaTypeNotSupportedException.class)
121	    @ResponseStatus(HttpStatus.UNSUPPORTED_MEDIA_TYPE)
122	    public R<Void> handleMediaTypeNotSupported(
123	            HttpMediaTypeNotSupportedException ex,
124	            HttpServletRequest request) {
125	        LOG.warn("Media type not supported: {}", ex.getContentType());
126	        return buildError(ResultCode.BAD_REQUEST,
127	                "Unsupported media type: " + ex.getContentType(),
128	                request);
129	    }
130	
131	    @ExceptionHandler(NoResourceFoundException.class)
132	    @ResponseStatus(HttpStatus.NOT_FOUND)
133	    public R<Void> handleNotFound(NoResourceFoundException ex,
134	                                  HttpServletRequest request) {
135	        return buildError(ResultCode.NOT_FOUND, request);
136	    }
137	
138	    @ExceptionHandler(Exception.class)
139	    @ResponseStatus(HttpStatus.INTERNAL_SERVER_ERROR)
140	    public R<Void> handleUnknown(Exception ex,
141	                                 HttpServletRequest request) {
142	        LOG.error("Unhandled exception at {} {}",
143	                request.getMethod(), request.getRequestURI(), ex);
144	        return buildError(ResultCode.INTERNAL_ERROR, request);
145	    }
146	
147	    /**
148	     * Builds error response with code, default message, trace, and path.
149	     */
150	    private static R<Void> buildError(@NonNull ResultCode code,
151	                                      @NonNull HttpServletRequest request) {
152	        R<Void> result = R.fail(code);
153	        result.setTraceId(MDC.get(TRACE_ID_KEY));
154	        result.setPath(request.getRequestURI());
155	        return result;
156	    }
157	
158	    /**
159	     * Builds error response with code, custom detail, trace, and path.
160	     */
161	    private static R<Void> buildError(@NonNull ResultCode code,
162	                                      @NonNull String detail,
163	                                      @NonNull HttpServletRequest request) {
164	        R<Void> result = R.fail(code, detail);
165	        result.setTraceId(MDC.get(TRACE_ID_KEY));
166	        result.setPath(request.getRequestURI());
167	        return result;
168	    }
169	
170	    /**
171	     * Builds error response with numeric code, message, trace, and path.
172	     */
173	    private static R<Void> buildError(int code,
174	                                      @NonNull String message,
175	                                      @NonNull HttpServletRequest request) {
176	        R<Void> result = R.fail(code, message);
177	        result.setTraceId(MDC.get(TRACE_ID_KEY));
178	        result.setPath(request.getRequestURI());
179	        return result;
180	    }
181	
182	    private static String getSimpleTypeName(
183	            MethodArgumentTypeMismatchException ex) {
184	        Class<?> requiredType = ex.getRequiredType();
185	        return requiredType != null
186	                ? requiredType.getSimpleName() : "unknown";
187	    }
188	}
